import { NextRequest } from 'next/server';

export function verifyAdminAuth(request: NextRequest): boolean {
  const token = request.cookies.get('admin_token')?.value;
  
  // Check if token exists
  if (!token) {
    console.log('No admin token found in cookies');
    return false;
  }

  // For production, verify the token is a valid hex string (generated by login)
  // This is a simple verification - in production you should use proper JWT
  const isValidToken = /^[a-f0-9]{64}$/.test(token);
  
  if (!isValidToken) {
    console.log('Invalid admin token format');
    return false;
  }

  console.log('Admin token verified successfully');
  return true;
}

// Fallback authentication for production debugging
export function verifyAdminAuthWithFallback(request: NextRequest): boolean {
  // Try normal authentication first
  if (verifyAdminAuth(request)) {
    return true;
  }

  // Fallback: Check for Authorization header (for debugging in production)
  const authHeader = request.headers.get('authorization');
  if (authHeader && authHeader.startsWith('Bearer ')) {
    const token = authHeader.substring(7);
    const isValidToken = /^[a-f0-9]{64}$/.test(token);
    if (isValidToken) {
      console.log('Admin token verified via Authorization header');
      return true;
    }
  }

  // Fallback: Check query parameter (for debugging in production)
  const url = new URL(request.url);
  const queryToken = url.searchParams.get('admin_token');
  if (queryToken) {
    const isValidToken = /^[a-f0-9]{64}$/.test(queryToken);
    if (isValidToken) {
      console.log('Admin token verified via query parameter');
      return true;
    }
  }

  console.log('All authentication methods failed');
  return false;
}

export function getVoterIP(request: NextRequest): string {
  return (request as any).ip || 
         request.headers.get('x-forwarded-for')?.split(',')[0] || 
         request.headers.get('x-real-ip') || 
         'unknown';
}

export function validateNIC(nic: string): boolean {
  const cleanNIC = nic.replace(/\s/g, '');
  
  // Old NIC format: 9 digits + V/v/X/x
  const oldNICPattern = /^[0-9]{9}[vVxX]$/;
  
  // New NIC format: 12 digits
  const newNICPattern = /^[0-9]{12}$/;
  
  return oldNICPattern.test(cleanNIC) || newNICPattern.test(cleanNIC);
}

export function validatePhone(phone: string): boolean {
  const cleanPhone = phone.replace(/\s/g, '');
  
  // Sri Lankan mobile phone formats:
  // +94 7X XXX XXXX (where X is 0,1,2,4,5,6,7,8)
  // 07X XXX XXXX (where X is 0,1,2,4,5,6,7,8)
  const phonePattern = /^(?:0|\+94)7[01245678][0-9]{7}$/;
  
  return phonePattern.test(cleanPhone);
}

export function validateEmail(email: string): boolean {
  const cleanEmail = email.trim().toLowerCase();
  
  // Basic email format validation
  const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!emailPattern.test(cleanEmail)) {
    return false;
  }
  
  // Additional validation for Sri Lankan context
  const [localPart, domain] = cleanEmail.split('@');
  
  // Check for common Sri Lankan email domains
  const srilankanDomains = [
    'gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com',
    'slt.lk', 'dialog.lk', 'mobitel.lk', 'etisalat.lk',
    'lanka.lk', 'sri.lanka', 'yahoo.lk', 'live.com'
  ];
  
  // Domain validation - should be a known provider or have proper format
  if (domain && !srilankanDomains.some(sld => domain.endsWith(sld))) {
    // Allow custom domains but with basic validation
    const domainPattern = /^[a-zA-Z0-9][a-zA-Z0-9-]*[a-zA-Z0-9]*\.[a-zA-Z]{2,}$/;
    if (!domainPattern.test(domain)) {
      return false;
    }
  }
  
  // Local part validation
  if (localPart.length < 2 || localPart.length > 64) {
    return false;
  }
  
  // No consecutive dots in local part
  if (localPart.includes('..')) {
    return false;
  }
  
  return true;
}

export function generateVoterId(): string {
  return `voter_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
}

export function generateCandidateId(): string {
  return `candidate_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
}

export function generateVoteId(): string {
  return `vote_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
}

export function sanitizeInput(input: string): string {
  return input.trim().replace(/[<>]/g, '');
}

export function rateLimitCheck(ip: string, maxRequests: number = 10, windowMs: number = 60000): boolean {
  // This is a simple in-memory rate limiter
  // In production, use Redis or similar for distributed rate limiting
  
  const requests = (global as any).rateLimitRequests || new Map();
  
  if (!requests.has(ip)) {
    requests.set(ip, { count: 1, resetTime: Date.now() + windowMs });
    (global as any).rateLimitRequests = requests;
    return true;
  }
  
  const requestData = requests.get(ip);
  
  if (Date.now() > requestData.resetTime) {
    requests.set(ip, { count: 1, resetTime: Date.now() + windowMs });
    return true;
  }
  
  if (requestData.count >= maxRequests) {
    return false;
  }
  
  requestData.count++;
  return true;
}

export function logSecurityEvent(event: string, details: any, request: NextRequest) {
  const logEntry = {
    timestamp: new Date().toISOString(),
    event,
    ip: getVoterIP(request),
    userAgent: request.headers.get('user-agent'),
    details
  };
  
  console.log('Security Event:', JSON.stringify(logEntry, null, 2));
  
  // In production, send to your logging service
  // e.g., Sentry, LogRocket, etc.
}

export async function checkIPHasVoted(ipAddress: string): Promise<boolean> {
  try {
    const { query } = await import('./database-clean');
    const result = await query('SELECT COUNT(*) as count FROM votes WHERE ipAddress = $1', [ipAddress]);
    return (result.rowCount !== null && result.rowCount > 0) && parseInt(result.rows[0]?.count || '0') > 0;
  } catch (error) {
    console.error('Error checking IP vote status:', error);
    return false;
  }
}

export function isValidIPAddress(ip: string): boolean {
  // Basic IP validation for IPv4
  const ipv4Pattern = /^(?:(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.){3}(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$/;
  
  // Basic IPv6 validation (simplified)
  const ipv6Pattern = /^(?:[0-9a-fA-F]{1,4}:){7}[0-9a-fA-F]{1,4}$/;
  
  // Allow private IP ranges and localhost
  const privateIPPattern = /^(?:10\.|192\.168\.|172\.(1[6-9]|2[0-9]|3[01])\.|127\.)/;
  
  return ipv4Pattern.test(ip) || ipv6Pattern.test(ip) || privateIPPattern.test(ip) || ip === 'localhost';
}
